'use strict';
// Extend the original pilot without changing learners’ saved lesson identifiers.
courses.push(...buildCurriculum(lesson));
courses[0].domain='tech';courses[1].domain='tech';courses[2].domain='tech';
state.lang=state.lang==='en'?'en':'fr';state.notes=state.notes||{};state.courseAccess=state.courseAccess||{};
const SUBJECTS=[['all','Tout explorer','✳'],['tech','Informatique','⌘'],['maths','Maths & données','½'],['sciences','Sciences & santé','◎'],['agri','Agriculture','❧'],['business','Commerce','↗'],['logistics','Logistique','⇄'],['creative','Création','✺'],['services','Services','☷']];
let subject='all',catalogQuery='',selectedDetail=null,selectedSector=null,lessonMode='read',walkStep=0,placementRun=null,validationRun=null;
const originalRender=render,originalNavigate=navigate,originalHome=homeView,originalOpenCourse=openCourse,originalProfile=profileModal,originalProgress=progressView;
function routeUrl(){return selectedDetail?'#/cours/'+selectedDetail:selectedSector?'#/metiers/'+selectedSector:'#/'+({home:'accueil',explore:'cours',downloads:'hors-ligne',progress:'progres',careers:'metiers'})[page]}
function routeFromUrl(){const bits=location.hash.replace(/^#\/?/,'').split('/');selectedDetail=bits[0]==='cours'&&courses.some(c=>c.id===bits[1])?bits[1]:null;selectedSector=bits[0]==='metiers'&&SECTORS.some(s=>s.id===bits[1])?bits[1]:null;page=({accueil:'home',home:'home',cours:'explore','hors-ligne':'downloads',progres:'progress',metiers:'careers'})[bits[0]]||'home';render()}
navigate=function(p){selectedDetail=null;selectedSector=null;originalNavigate(p);history.pushState({},'',routeUrl())};
render=function(){originalRender();if($('.nav-pill'))$('.nav-pill').textContent=String(courses.length);if(selectedDetail)$('#breadcrumb-current').textContent=getCourse(selectedDetail).title;if(selectedSector)$('#breadcrumb-current').textContent=SECTORS.find(s=>s.id===selectedSector).title;const badges=$$('[data-i="explore"]');badges.forEach(b=>b.textContent='Tous les cours');$('#language-label').textContent=state.lang==='en'?'EN':'FR';};
function openDetail(id){selectedSector=null;selectedDetail=id;page='explore';history.pushState({},'',routeUrl());render();window.scrollTo({top:0,behavior:'instant'})}
function openSector(id){selectedDetail=null;selectedSector=id;page='careers';history.pushState({},'',routeUrl());render();window.scrollTo({top:0,behavior:'instant'})}
function subjectName(id){return SUBJECTS.find(s=>s[0]===id)?.[1]||'Découverte'}
function lessonUnlocked(c,i){return i===0||state.courseAccess[c.id]||state.done.includes(c.id+':'+i)||c.lessons.slice(0,i).every((_,n)=>state.done.includes(c.id+':'+n))}
function courseVisual(c){if(c.type!=='subject')return art(c);return `<div class="subject-art-icon">${esc(c.glyph)}</div><div class="art-lines"><i></i><i></i><i></i></div>`}
courseCard=function(c){const vids=LEARNING_VIDEOS[c.id]||[];return `<article class="course-card ${c.type} modern-course"><button class="course-art ${c.type}" data-detail="${c.id}" aria-label="Découvrir ${esc(c.title)}" style="${c.color?'background:'+c.color:''}"><span class="course-badge" aria-hidden="true">${icon('download')} Texte hors ligne</span><span aria-hidden="true">${courseVisual(c)}</span><span class="art-number" aria-hidden="true">${String(courses.indexOf(c)+1).padStart(2,'0')}</span></button><div class="course-body"><span class="course-category">${esc(c.category)}</span><h3><button data-detail="${c.id}">${esc(c.title)}</button></h3><p>${esc(c.desc)}</p><div class="course-meta"><span>${icon('book')}${c.lessons.length} leçons</span><span>${icon('clock')}${c.duration} min</span><span>${vids.length?'▷ Vidéo en option':'✎ Exercices inclus'}</span></div>${doneCount(c)?`<div class="progress-line" style="margin-bottom:12px"><span style="width:${pct(c)}%"></span></div>`:''}<div class="course-action-row"><button data-detail="${c.id}">${doneCount(c)?'Continuer le parcours':'Voir le programme'} ${icon('arrow')}</button><button class="download-btn" data-download="${c.id}" aria-label="${state.downloads.includes(c.id)?'Parcours enregistré':'Enregistrer '+esc(c.title)}">${icon(state.downloads.includes(c.id)?'check':'download')}</button></div></div></article>`};
homeView=function(){let html=originalHome();const welcome=state.placement?`<div class="personal-path-banner"><span class="path-spark">✧</span><div><strong>Ton point de départ : ${esc(getCourse(state.placement.recommended).title)}</strong><p>Un repère pour commencer. Tu peux explorer tous les autres domaines.</p></div><button class="secondary" data-do="placement">Me réévaluer</button></div>`:`<section class="placement-invite"><div><span class="eyebrow">UN CHEMIN QUI TE RESSEMBLE</span><h2>Ta curiosité mérite un bon point de départ.</h2><p>10 petites questions pour repérer tes bases. Pas de note, pas de pression.</p></div><button class="primary" data-do="placement">Trouver mon parcours ${icon('arrow')}</button></section>`;html=html.replace('<section class="recommended">',welcome+'<section class="recommended">');if(state.followedPath){const [sid,idx]=state.followedPath.split(':');const sec=SECTORS.find(s=>s.id===sid),job=sec?.jobs[Number(idx)];if(job)html=html.replace('<section class="recommended">',`<section class="followed-career"><span style="background:${sec.color}">${sec.icon}</span><div><small>LE CHEMIN QUE TU AS CHOISI</small><strong>${esc(job.name)}</strong><p>${job.path.filter(id=>pct(getCourse(id))===100).length} / ${job.path.length} cours explorés jusqu’au bout</p></div><button class="secondary" data-sector="${sid}">Retrouver mon chemin →</button></section><section class="recommended">`)}const key='<div class="hero-end-note">';const sectorPreview=`<section class="sector-home"><div class="section-heading"><h2>Et toi, qu’aimerais-tu devenir ?</h2><button class="text-button" data-page="careers">Tous les métiers ${icon('arrow')}</button></div><div class="sector-ribbon">${SECTORS.slice(0,6).map(s=>`<button data-sector="${s.id}" style="--tile:${s.color}"><span>${s.icon}</span><strong>${s.short}</strong><small>${s.jobs.length} chemins à découvrir ↗</small></button>`).join('')}</div></section>`;html=html.replace(key,sectorPreview+key);const wrapper=document.createElement('div');wrapper.innerHTML=html;const grid=wrapper.querySelector('.recommended .course-grid');grid.innerHTML=courses.slice(0,3).map(courseCard).join('');return wrapper.innerHTML};
exploreView=function(){if(selectedDetail)return detailView(getCourse(selectedDetail));const filtered=courses.filter(c=>(subject==='all'||c.domain===subject)&&normalize(c.title+' '+c.desc+' '+c.category).includes(normalize(catalogQuery)));return `<section class="catalog-hero"><div><span class="eyebrow">LE MONDE EST PLUS GRAND QUE CE QU’ON CONNAÎT</span><h1>Une curiosité.<br><em>Mille possibilités.</em></h1><p>Du premier clic au premier projet. Trouve un sujet qui te donne envie, on avance ensemble.</p><div class="catalog-facts"><span>${courses.length} parcours</span><i></i><span>${courses.reduce((n,c)=>n+c.lessons.length,0)} leçons en français</span><i></i><span>Gratuit, à ton rythme</span></div></div><div class="catalog-art" aria-hidden="true"><div class="floating-card fc-one">&lt;/&gt;<small>CRÉER</small></div><div class="floating-card fc-two">½<small>COMPRENDRE</small></div><div class="floating-card fc-three">❧<small>EXPLORER</small></div><span class="catalog-spark">✳</span><span class="orbit-dot"></span></div></section><section class="catalog-tools"><div class="catalog-heading"><div><h2>Qu’as-tu envie d’apprendre ?</h2><p>Choisis un domaine ou laisse-toi surprendre.</p></div><label class="catalog-search">${icon('search')}<input id="catalog-search" type="search" value="${esc(catalogQuery)}" placeholder="Un cours, une compétence…" aria-label="Rechercher dans les cours"></label></div><div class="subject-tabs" role="group" aria-label="Domaines">${SUBJECTS.map(([id,name,glyph])=>`<button class="subject-tab ${subject===id?'selected':''}" data-subject="${id}" aria-pressed="${subject===id}"><span>${glyph}</span>${name}</button>`).join('')}</div></section><div class="catalog-results-line"><span>${filtered.length} parcours ${subject==='all'?'à explorer':'en '+subjectName(subject).toLowerCase()}</span><span>✓ Articles &nbsp; ✎ Exercices &nbsp; ▷ Vidéos en option</span></div><div class="course-grid explore-grid" id="catalog-grid">${filtered.length?filtered.map(courseCard).join(''):'<div class="empty-state" style="grid-column:1/-1"><h3>Pas encore de résultat pour cette recherche.</h3><p>Essaie « Python », « données », « agriculture » ou change de domaine.</p><button class="secondary" data-do="clear-search">Tout afficher</button></div>'}</div><section class="catalog-bottom-banner"><span>✳</span><div><h3>Un métier en tête ? On peut commencer par là.</h3><p>Des parcours de découverte reliés aux secteurs du Togo.</p></div><button class="primary" data-page="careers">Explorer les métiers →</button></section>`};
function normalize(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function detailView(c){const videos=LEARNING_VIDEOS[c.id]||[],related=SECTORS.flatMap(s=>s.jobs.filter(j=>j.path.includes(c.id)).map(j=>({s,j}))).slice(0,3);return `<button class="back-link" data-do="back-catalog">← Tous les cours</button><section class="course-detail-hero" style="--detail:${c.color||'#e1ead6'}"><div><span class="eyebrow">${esc(c.category)} · INITIATION</span><h1>${esc(c.title)}</h1><p>${esc(c.desc)}</p><div class="detail-facts"><span>${icon('book')}${c.lessons.length} leçons</span><span>${icon('clock')}${c.duration} min environ</span><span>◉ Débutant</span></div><div class="modal-actions"><button class="primary" data-course="${c.id}">${doneCount(c)?'Continuer mon parcours':'Commencer à apprendre'} →</button><button class="secondary" data-download="${c.id}">${icon(state.downloads.includes(c.id)?'check':'download')}${state.downloads.includes(c.id)?'Enregistré hors ligne':'Emporter ce cours'}</button></div></div><div class="detail-symbol" aria-hidden="true">${c.glyph||({'python':'Py','web':'</>','digital':'@'})[c.id]}</div></section><div class="course-detail-grid"><section><div class="section-heading"><h2>Un pas après l’autre.</h2><span class="profile-line">${doneCount(c)} / ${c.lessons.length} validées</span></div><div class="syllabus">${c.lessons.map((l,i)=>{const unlocked=lessonUnlocked(c,i),done=state.done.includes(c.id+':'+i);return `<button class="syllabus-lesson ${done?'done':''} ${unlocked?'':'locked'}" data-course="${c.id}" data-index="${i}" ${unlocked?'':'aria-disabled="true"'}><span class="lesson-circle">${done?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong><small>Article · exemple pas à pas · exercice${videos.some(v=>v.lessons.includes(i))?' · vidéo en option':''}</small></span><span class="syllabus-end">${unlocked?'10 min &nbsp; →':'À débloquer'}</span></button>`}).join('')}</div><div class="info-banner">${icon('compass')}<div><strong>Tu connais déjà les bases ?</strong><p>Un mini-défi permet d’ouvrir toutes les leçons, sans les compter comme terminées.</p><button class="text-button" style="margin-top:10px" data-validate="${c.id}">Vérifier mes acquis →</button></div></div></section><aside class="detail-aside"><div class="panel methods-card"><span class="eyebrow">TA FAÇON D’APPRENDRE</span><h3>Tu choisis le déclic.</h3><div><span>01</span><p><strong>Lire & comprendre</strong>Une explication claire, avec un exemple local.</p></div><div><span>02</span><p><strong>Avancer pas à pas</strong>Déplie un raisonnement, une étape à la fois.</p></div><div><span>03</span><p><strong>Essayer & réessayer</strong>Des exercices sans pénalité et un carnet personnel.</p></div>${videos.length?'<div><span>04</span><p><strong>Voir autrement</strong>Une vidéo en français, seulement si tu le souhaites.</p></div>':''}<small>Les articles et exercices sont enregistrables. Les vidéos nécessitent une connexion et ne sont pas téléchargées.</small></div>${related.length?`<div class="panel related-jobs"><h3>Ça peut mener vers…</h3>${related.map(({s,j})=>`<button data-sector="${s.id}">${esc(j.name)} <span>↗</span></button>`).join('')}<p>Des pistes d’orientation, pas une qualification professionnelle.</p></div>`:''}</aside></div>`}
careersView=function(){if(selectedSector)return sectorView(SECTORS.find(s=>s.id===selectedSector));return `<section class="career-intro"><span class="eyebrow">APPRENDRE AUJOURD’HUI, IMAGINER LA SUITE</span><h1 class="page-title">Quel avenir veux-tu explorer ?</h1><p class="page-subtitle">Découvre des métiers, les compétences qui les rapprochent et un premier chemin pour essayer. Tout commence par la curiosité.</p></section><div class="sector-grid">${SECTORS.map((s,i)=>`<button class="sector-tile" data-sector="${s.id}" style="--tile:${s.color}"><div class="sector-tile-art"><span>${s.icon}</span><i>${String(i+1).padStart(2,'0')}</i><b>↗</b></div><div class="sector-tile-text"><h2>${s.title}</h2><p>${s.desc}</p><small>${s.jobs.length} métiers · des cours pour commencer</small></div></button>`).join('')}</div><div class="sector-evidence"><span>${icon('compass')}</span><div><strong>Des chemins ancrés au Togo.</strong><p>Le numérique, l’agriculture, l’énergie, la logistique et les petites entreprises s’appuient sur les secteurs présentés dans la stratégie pays de la Banque mondiale. Santé, création et accueil complètent les pistes d’orientation. Ces choix sont pédagogiques : aucune promesse d’embauche ni offre en temps réel.</p><details><summary>Comment les domaines ont-ils été choisis ?</summary><p>Contexte consulté le 1er novembre 2026 : <a href="https://www.banquemondiale.org/ext/fr/country/togo" target="_blank" rel="noopener">Banque mondiale — Togo</a>. Les parcours associent des cours d’initiation à des compétences utiles ; les métiers et débouchés doivent être affinés avec des professionnels et des établissements togolais.</p></details></div></div>`};
function sectorView(s){return `<button class="back-link" data-do="back-sectors">← Tous les domaines métiers</button><section class="sector-detail-head" style="--tile:${s.color}"><span class="sector-big-symbol">${s.icon}</span><div><span class="eyebrow">UN DOMAINE, PLUSIEURS POSSIBLES</span><h1>${s.title}</h1><p>${s.desc}</p></div></section><p class="sector-context">${esc(s.context)}</p>${s.jobs.map((j,index)=>`<section class="job-path"><div class="job-path-heading"><span class="job-number">0${index+1}</span><div><h2>${esc(j.name)}</h2><p>${esc(j.intro)}</p></div><button class="secondary" data-follow="${s.id}:${index}">${state.followedPath===s.id+':'+index?'✓ Chemin choisi':'Choisir ce chemin'}</button></div><div class="path-steps">${j.path.map((id,n)=>{const c=getCourse(id);return `<button data-detail="${id}" class="path-step ${pct(c)===100?'completed':''}"><span>${pct(c)===100?'✓':n+1}</span><strong>${esc(c.title)}</strong><small>${c.lessons.length} leçons · ${doneCount(c)?pct(c)+' %':'Découvrir'} →</small></button>`}).join('')}</div><div class="job-next"><span>ET ENSUITE ?</span><p>${esc(j.next)}</p></div></section>`).join('')}`}
profileModal=function(){originalProfile();const form=$('#profile-form');form.querySelector('.two-fields').insertAdjacentHTML('beforebegin',`<label class="field">Ta tranche d’âge (facultatif)<select name="ageBand"><option value="">Je préfère ne pas préciser</option>${['13–15 ans','16–18 ans','19–24 ans','25 ans et plus'].map(x=>`<option ${state.profile.ageBand===x?'selected':''}>${x}</option>`).join('')}</select></label>`)};
openCourse=function(id,index){const c=getCourse(id);let n=index===undefined?nextLesson(c):index;if(!lessonUnlocked(c,n)){toast('Une étape à la fois : termine la leçon précédente ou vérifie tes acquis.');return}lessonMode='read';walkStep=0;originalOpenCourse(id,n)};
renderLesson=function(){const c=activeCourse,l=c.lessons[activeLesson],videos=(LEARNING_VIDEOS[c.id]||[]).filter(v=>v.lessons.includes(activeLesson));modal(`<div class="reader-topline"><span class="lesson-label">${esc(c.title)} · ${activeLesson+1}/${c.lessons.length}</span><span class="reader-status">${state.downloads.includes(c.id)?'✓ Enregistré hors ligne':'10 minutes pour toi'}</span></div><h2 id="modal-title">${esc(l.title)}</h2><div class="reader-tabs" role="tablist" aria-label="Façons d’apprendre"><button role="tab" data-mode="read" aria-selected="true">${icon('book')} Lire</button><button role="tab" data-mode="steps" aria-selected="false">↳ Pas à pas</button><button role="tab" data-mode="practice" aria-selected="false">✎ Pratiquer</button>${videos.length?'<button role="tab" data-mode="video" aria-selected="false">▷ Vidéo</button>':''}</div><div class="lesson-layout"><nav class="lesson-nav" aria-label="Leçons du parcours">${c.lessons.map((x,i)=>`<button data-lesson="${i}" class="${i===activeLesson?'current ':''}${state.done.includes(c.id+':'+i)?'complete':''}" ${!lessonUnlocked(c,i)?'disabled aria-label="Leçon verrouillée : '+esc(x.title)+'"':''} ${i===activeLesson?'aria-current="step"':''}><span>${state.done.includes(c.id+':'+i)?'✓':String(i+1).padStart(2,'0')}</span>${esc(x.title)}</button>`).join('')}<button class="reader-programme" data-return-course="${c.id}">← Le programme complet</button></nav><div class="lesson-content"><div id="reading-panel" class="learning-panel"><span class="tag">UNE IDÉE À COMPRENDRE</span><p>${esc(l.body)}</p><span class="example-heading">Un exemple concret</span><pre><code>${esc(l.code)}</code></pre><div class="example-output"><span class="output-label">CE QU’ON OBTIENT</span>${esc(l.output).replace(/\n/g,'<br>')}</div><button class="text-button" style="margin-top:17px" data-mode="steps">Déplier le raisonnement pas à pas →</button></div><div id="steps-panel" class="learning-panel" hidden><span class="tag">PRENDS LE TEMPS DE COMPRENDRE</span><h3 style="margin-top:12px">Un raisonnement, plusieurs petits pas.</h3><div id="walkthrough"></div><div class="modal-actions"><button class="secondary" data-walk="prev">← Revenir</button><button class="primary" data-walk="next">Étape suivante →</button></div></div><div id="video-panel" class="learning-panel" hidden>${videos.map((v,i)=>videoBlock(v,i)).join('')}<div class="video-fallback"><strong>Pas de réseau, ou envie de lire ?</strong><p>Tout ce qu’il faut pour répondre à l’exercice est dans l’article. La vidéo est un complément, pas un passage obligé.</p><button class="secondary" data-mode="read">Revenir à l’explication</button></div></div><section class="quiz-section" id="practice-panel"><span class="tag">À TOI DE JOUER · ESSAIS ILLIMITÉS</span><h3 style="font-size:17px;margin-top:12px">${esc(l.question)}</h3><div id="quiz-options">${l.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}" aria-pressed="false">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div><div class="modal-actions"><button class="primary" id="check-answer">Vérifier ma réponse ✓</button><button class="secondary" data-action="lesson-help">Un indice ?</button></div></section><section class="reflection"><span class="tag">AVEC TES MOTS</span><h3>Et toi, comment l’expliquerais-tu ?</h3><label for="lesson-note">Une phrase, un exemple ou une question à garder.</label><textarea id="lesson-note" maxlength="2000" rows="3" placeholder="Ce que j’ai compris…">${esc(state.notes[c.id+':'+activeLesson]||'')}</textarea><button class="text-button" data-do="save-note">Enregistrer dans mon carnet ✓</button><small>Ton texte reste sur cet appareil. Il n’est pas évalué automatiquement.</small></section>${sourceBlock(c,videos)}</div></div>`,true);setLessonMode(lessonMode);};
function videoBlock(v,i){return `<article class="video-lesson"><div class="video-screen" id="video-slot-${i}"><button class="video-load" data-video="${v.id}" data-slot="${i}"><span class="play-circle">▶</span><strong>${esc(v.title)}</strong><small>Lire ici · vidéo en français</small></button></div><div class="video-caption"><strong>${esc(v.author)}</strong><span>${esc(v.note)}</span>${v.license?`<small>${esc(v.license)}</small>`:''}</div><p class="video-data-note">Le lecteur YouTube se charge uniquement à ton clic et utilise une connexion. La qualité se règle dans le lecteur.</p><button class="text-button" data-do="video-problem">La vidéo ne fonctionne pas ?</button></article>`}
function sourceBlock(c,videos){const sources=LEARNING_SOURCES[c.id]||[];return `<details class="lesson-sources"><summary>Sources & crédits de cette leçon</summary><p>Explications, exemples et exercices : rédaction originale Nunya. Les vidéos sont affichées dans leur lecteur officiel, sans copie ni traduction de leur contenu.</p>${videos.map(v=>`<p>${esc(v.title)} — ${esc(v.author)}${v.license?' · '+esc(v.license):''}.</p>`).join('')}${sources.map(([name,url,note])=>`<p><a href="${url}" target="_blank" rel="noopener">${esc(name)}</a> — ${esc(note)}</p>`).join('')}<p>Nunya est indépendant de Khan Academy, YouTube, freeCodeCamp et Class Central. Aucune affiliation n’est revendiquée.</p></details>`}
function setLessonMode(mode){lessonMode=mode;$$('.reader-tabs [data-mode]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.mode===mode)));$('#reading-panel').hidden=mode!=='read';$('#steps-panel').hidden=mode!=='steps';$('#video-panel').hidden=mode!=='video';$('#practice-panel').hidden=mode!=='read'&&mode!=='practice';$('.reflection').hidden=mode!=='read'&&mode!=='practice';if(mode==='steps')renderWalkthrough();}
function walkSteps(){const l=activeCourse.lessons[activeLesson];return [{title:'D’abord, l’idée',text:l.body},{title:'Observe l’exemple',code:l.code},{title:'Fais une prédiction',text:'Avant de regarder la réponse, essaie de prévoir ce que l’exemple va produire. Tu peux noter ton raisonnement sur une feuille.'},{title:'Compare avec le résultat',code:l.output},{title:'Vérifie ta compréhension',text:l.question}]}
function renderWalkthrough(){const steps=walkSteps();walkStep=Math.max(0,Math.min(steps.length-1,walkStep));const step=steps[walkStep];$('#walkthrough').innerHTML=`<div class="walk-progress">${steps.map((s,i)=>`<span class="${i<=walkStep?'filled':''}"></span>`).join('')}</div><span class="step-count">ÉTAPE ${walkStep+1} SUR ${steps.length}</span><h3>${step.title}</h3>${step.code?`<pre><code>${esc(step.code)}</code></pre>`:`<p>${esc(step.text)}</p>`}${walkStep===steps.length-1?'<button class="secondary" data-mode="practice">À moi d’essayer →</button>':''}`;$('[data-walk="prev"]').disabled=walkStep===0;$('[data-walk="next"]').disabled=walkStep===steps.length-1;}
const PLACEMENT_BASE=[
{q:'Tu veux retrouver un document sur ton téléphone. Où cherches-tu en premier ?',o:['Dans les fichiers ou l’application où il a été enregistré','Dans le chargeur','Dans le volume du son'],a:0,skill:'digital'},
{q:'« Enregistre ta leçon avant de quitter le réseau. » Que faut-il faire en premier ?',o:['Couper Internet','Enregistrer la leçon pendant la connexion','Changer de téléphone'],a:1,skill:'reading'},
{q:'Une recette contient 4 étapes. Pourquoi leur ordre peut-il compter ?',o:['Certaines étapes ont besoin du résultat des précédentes','Il ne compte jamais','Pour avoir plus de couleurs'],a:0,skill:'logic'},
{q:'Un cahier coûte 250 FCFA. À prix identique, deux cahiers coûtent…',o:['250 FCFA','500 FCFA','750 FCFA'],a:1,skill:'maths'},
{q:'Une variable peut être comparée à…',o:['Une boîte nommée contenant une valeur','Une vidéo','Un chargeur'],a:0,skill:'code'},
{q:'Le programme commence avec points = 2 puis ajoute 3. Quelle valeur obtient-il ?',o:['23','3','5'],a:2,skill:'code'},
{q:'Pour garder ton compte en sécurité, tu dois…',o:['Partager ton code de connexion','Garder ton code de connexion privé','Publier ton mot de passe'],a:1,skill:'digital'},
{q:'Dans « répéter pour chaque article », quelle idée apparaît ?',o:['Une boucle','Une image','Un mot de passe'],a:0,skill:'logic'}
];
const PLACEMENT_EXTRA={easy:[{q:'Sur 4 parts égales, 2 parts représentent…',o:['La moitié','Le double','Toutes les parts'],a:0,skill:'maths'},{q:'Un article explique une idée difficile. Que peux-tu faire ?',o:['Reprendre l’exemple une étape à la fois','Abandonner définitivement','Partager des données privées'],a:0,skill:'reading'}],hard:[{q:'Une boucle répète une action pour 0, 1 et 2. Combien de répétitions ?',o:['2','3','4'],a:1,skill:'code'},{q:'Pour filtrer les lignes d’une table SQL, on utilise…',o:['WHERE','PRINT','COLOR'],a:0,skill:'code'}]};
function startPlacement(){placementRun={index:0,answers:[],questions:[...PLACEMENT_BASE],selected:null};showPlacement()}
function showPlacement(){const run=placementRun;if(run.index===8&&run.questions.length===8){const score=run.answers.filter(x=>x.right).length;run.questions.push(...PLACEMENT_EXTRA[score>=6?'hard':'easy'])}if(run.index===10){finishPlacement();return}const q=run.questions[run.index];modal(`<span class="eyebrow">TON POINT DE DÉPART · ${run.index+1}/10</span><h2 id="modal-title">On découvre ce que tu sais déjà.</h2><p>Ce n’est pas un examen. « Je découvre » est aussi une réponse utile.</p><div class="progress-line" style="margin:20px 0"><span style="width:${run.index*10}%"></span></div><h3 class="assessment-question">${esc(q.q)}</h3><div>${q.o.map((o,i)=>`<button class="assessment-option" data-placement-answer="${i}" aria-pressed="false">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}<button class="assessment-option unsure" data-placement-answer="-1" aria-pressed="false">Je découvre cette notion</button></div><div class="modal-actions"><button class="primary" id="placement-next" disabled>Continuer →</button></div>`)}
function finishPlacement(){const answers=placementRun.answers,score=answers.filter(a=>a.right).length,code=answers.filter(a=>a.skill==='code'&&a.right).length;const recommended=score<=4?'digital':code<=1?'algorithms':code<=3?'python':'javascript';state.placement={date:dayKey(),recommended,answered:10,skills:{digital:answers.filter(a=>a.skill==='digital'&&a.right).length,logic:answers.filter(a=>a.skill==='logic'&&a.right).length,code},score};state.lastCourse=recommended;persist();render();modal(`<div class="onboarding-art">🌱</div><h2 id="modal-title">On a trouvé un premier chemin.</h2><p>Ce repère ne te définit pas. Tu peux changer de domaine et revenir sur une notion quand tu veux.</p><div class="assessment-result"><span class="eyebrow">POUR COMMENCER SEREINEMENT</span><h3>${getCourse(recommended).title}</h3><p>${getCourse(recommended).desc}</p></div><div class="modal-actions"><button class="primary" data-placement-start="${recommended}">Découvrir mon parcours →</button><button class="secondary" data-do="placement-explore">Explorer librement</button></div>`)}
function startValidation(id){const c=getCourse(id);validationRun={c,index:0,right:0,selected:null,items:c.lessons.slice(0,3)};showValidation()}
function showValidation(){const r=validationRun;if(r.index>=r.items.length){if(r.right===r.items.length){state.courseAccess[r.c.id]=true;persist();render()}modal(`<div class="onboarding-art">${r.right===r.items.length?'✧':'🌱'}</div><h2 id="modal-title">${r.right===r.items.length?'Tu peux explorer toutes les leçons.':'On garde un chemin progressif.'}</h2><p>${r.right===r.items.length?'Tes acquis permettent d’ouvrir les chapitres. Les leçons ne sont comptées comme terminées qu’après leur exercice.':'Certaines bases méritent un détour. Reprends les premières leçons : tu pourras retenter ce mini-défi quand tu voudras.'}</p><button class="primary" data-validation-return="${r.c.id}">Voir mon programme →</button>`);return}const l=r.items[r.index];modal(`<span class="eyebrow">VÉRIFIER MES ACQUIS · ${r.index+1}/${r.items.length}</span><h2 id="modal-title">Un raccourci, si tu es à l’aise.</h2><p>${esc(l.question)}</p>${l.options.map((o,i)=>`<button class="assessment-option" data-validation-answer="${i}" aria-pressed="false">${esc(o)}</button>`).join('')}<div class="modal-actions"><button class="primary" id="validation-next" disabled>Continuer →</button></div>`)}
progressView=function(){let html=originalProgress();const notes=Object.entries(state.notes).filter(([,text])=>text.trim());html+=`<section class="panel notebook"><div class="section-heading"><h3>Mon carnet de découvertes</h3><span class="tag">${notes.length} NOTES</span></div>${notes.length?notes.map(([key,text])=>{const [id,n]=key.split(':');const c=getCourse(id);return `<article><span class="eyebrow">${esc(c.title)}</span><strong>${esc(c.lessons[Number(n)]?.title||'Ma note')}</strong><p>${esc(text).replace(/\n/g,'<br>')}</p><button class="text-button" data-course="${id}" data-index="${n}">Revoir la leçon →</button></article>`}).join(''):'<p>À la fin d’une leçon, écris une idée avec tes mots. Retrouve-la ici pour la réviser.</p>'}</section>`;return html};
function saveNote(){state.notes[activeCourse.id+':'+activeLesson]=$('#lesson-note').value.trim().slice(0,2000);if(persist())toast('Ta note est enregistrée dans ton carnet.');}
// Handle new controls before the original delegated click handler.
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;let handled=true;if(b.id==='next-lesson'||b.dataset.lesson!==undefined){lessonMode='read';walkStep=0}if(b.dataset.detail)openDetail(b.dataset.detail);else if(b.dataset.sector)openSector(b.dataset.sector);else if(b.dataset.subject){subject=b.dataset.subject;render()}else if(b.dataset.mode)setLessonMode(b.dataset.mode);else if(b.dataset.walk){walkStep+=b.dataset.walk==='next'?1:-1;renderWalkthrough()}else if(b.dataset.returnCourse){closeModal();openDetail(b.dataset.returnCourse)}else if(b.dataset.video){if(!navigator.onLine){toast('Tu es hors ligne. L’article et l’exercice restent disponibles.');return}const v=(LEARNING_VIDEOS[activeCourse.id]||[]).find(v=>v.id===b.dataset.video);if(!v)return;$('#video-slot-'+b.dataset.slot).innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${v.id}?rel=0&hl=fr&playsinline=1" title="${esc(v.title)} — ${esc(v.author)}" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;}else if(b.dataset.validate)startValidation(b.dataset.validate);else if(b.dataset.placementAnswer!==undefined){placementRun.selected=Number(b.dataset.placementAnswer);$$('[data-placement-answer]').forEach(x=>{x.setAttribute('aria-pressed',String(x===b));x.classList.toggle('selected',x===b)});$('#placement-next').disabled=false}else if(b.id==='placement-next'){const q=placementRun.questions[placementRun.index];placementRun.answers.push({skill:q.skill,right:placementRun.selected===q.a});placementRun.index++;placementRun.selected=null;showPlacement()}else if(b.dataset.placementStart){closeModal();openDetail(b.dataset.placementStart)}else if(b.dataset.validationAnswer!==undefined){validationRun.selected=Number(b.dataset.validationAnswer);$$('[data-validation-answer]').forEach(x=>{x.setAttribute('aria-pressed',String(x===b));x.classList.toggle('selected',x===b)});$('#validation-next').disabled=false}else if(b.id==='validation-next'){if(validationRun.selected===validationRun.items[validationRun.index].answer)validationRun.right++;validationRun.index++;validationRun.selected=null;showValidation()}else if(b.dataset.validationReturn){closeModal();openDetail(b.dataset.validationReturn)}else if(b.dataset.follow){state.followedPath=b.dataset.follow;const [sid,n]=b.dataset.follow.split(':');state.lastCourse=SECTORS.find(s=>s.id===sid).jobs[Number(n)].path.find(id=>pct(getCourse(id))<100)||'digital';persist();render();toast('Chemin ajouté à ton espace. Tu peux commencer par le premier cours.')}else if(b.dataset.do){const actions={'placement':startPlacement,'back-catalog':()=>{selectedDetail=null;history.pushState({},'','#/cours');render()},'back-sectors':()=>{selectedSector=null;history.pushState({},'','#/metiers');render()},'clear-search':()=>{catalogQuery='';subject='all';render()},'save-note':saveNote,'placement-explore':()=>{closeModal();navigate('explore')},'video-problem':()=>{$('.video-fallback').scrollIntoView({behavior:'smooth',block:'center'});toast('Essaie l’article ou le pas à pas. Tu peux aussi signaler la vidéo dans « Donner mon avis ».')}};if(actions[b.dataset.do])actions[b.dataset.do]();else handled=false}else handled=false;if(b.id==='close-modal'&&typeof speechSynthesis!=='undefined')speechSynthesis.cancel();if(handled)e.stopImmediatePropagation()},true);
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){catalogQuery=e.target.value;const input=e.target,position=input.selectionStart;const visible=courses.filter(c=>(subject==='all'||c.domain===subject)&&normalize(c.title+' '+c.desc+' '+c.category).includes(normalize(catalogQuery)));$('#catalog-grid').innerHTML=visible.length?visible.map(courseCard).join(''):'<div class="empty-state" style="grid-column:1/-1"><h3>Aucun parcours trouvé.</h3><p>Essaie une autre idée, ou change de domaine.</p><button class="secondary" data-do="clear-search">Tout afficher</button></div>';$('.catalog-results-line>span').textContent=visible.length+' parcours à explorer';hydrate();} });
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){const f=new FormData(e.target);const age=f.get('ageBand');setTimeout(()=>{state.profile.ageBand=String(age||'');persist()},0)}},true);
const oldExport=exportProgress;exportProgress=function(){downloadJSON({format:'nunya-backup-v1',profile:state.profile,done:state.done,activity:state.activity,minutes:state.minutes,lang:state.lang,notes:state.notes,courseAccess:state.courseAccess,placement:state.placement,followedPath:state.followedPath},'nunya-progression-'+dayKey()+'.json');toast('Sauvegarde exportée avec ton carnet et tes progrès.')};
$('.brand').addEventListener('click',e=>{e.preventDefault();navigate('home')});
$('#help-btn').insertAdjacentHTML('beforebegin','<button class="help-button feedback-nav" data-action="feedback"><span>♡</span><span>Donner mon avis</span><span>↗</span></button>');
