// Keep the off-canvas mobile menu out of keyboard navigation while closed.
function syncMenuAccess(){const side=$('#sidebar');side.inert=!$('#modal').hidden||(matchMedia('(max-width:700px)').matches&&!side.classList.contains('open'));$('#menu-btn').setAttribute('aria-expanded',String(side.classList.contains('open')))}
const baseMenuClick=$('#menu-btn').onclick;$('#menu-btn').onclick=()=>{baseMenuClick();syncMenuAccess()};window.addEventListener('resize',syncMenuAccess);const renderWithMenu=render;render=function(){renderWithMenu();syncMenuAccess()};const closeWithMenu=closeModal;closeModal=function(){closeWithMenu();syncMenuAccess()};syncMenuAccess();

$('#close-modal').addEventListener('click',syncMenuAccess);
